  "<a href=\"index.html#fonctionnalites\">Fonctionnalités</a> <a href=\"index.html#video\">Vidéo</a> <a href=\"index.html#offres\">Offres</a> <a href=\"#\" data-lien=\"CONNEXION\">Se connecter</a> <a class=\"bouton bouton-plein\" href=\"inscription.html\">Créer mon espace</a>": "<a href=\"index.html#fonctionnalites\">Funktionen</a> <a href=\"index.html#video\">Video</a> <a href=\"index.html#offres\">Angebote</a> <a href=\"#\" data-lien=\"CONNEXION\">Anmelden</a> <a class=\"bouton bouton-plein\" href=\"inscription.html\">Meinen Bereich erstellen</a>",
